SELECT u.channel AS channel, ROUND(AVG(retained_90)::numeric,4) AS retention_90
FROM (
  SELECT du.user_id, du.channel, du.signup_date,
    CASE WHEN EXISTS (
      SELECT 1 FROM fct_user_days ud WHERE ud.user_id = du.user_id AND ud.active_date BETWEEN du.signup_date AND du.signup_date + INTERVAL '90 day'
    ) THEN 1 ELSE 0 END AS retained_90
  FROM dim_users du
) s
GROUP BY channel
ORDER BY retention_90 DESC;

SELECT channel, ROUND(AVG(retained_90)::numeric,4) AS retention_90
FROM (
  SELECT du.user_id, du.channel AS channel, du.signup_date,
    CASE WHEN EXISTS (
      SELECT 1 FROM fct_user_days ud WHERE ud.user_id = du.user_id AND ud.active_date BETWEEN du.signup_date AND du.signup_date + INTERVAL '90 day'
    ) THEN 1 ELSE 0 END AS retained_90
  FROM dim_users du
) s
GROUP BY channel
ORDER BY retention_90 DESC;
